import java.util.Scanner;

public class Main {
    public static long computeGCD(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        long limit = sc.nextLong();

        long bestNum = 0;
        long bestDen = 1;
        double minDifference = 1e12;

        for (long denom = 1; denom <= limit; denom++) {
            long left = 0, right = 100000;
            long numerator = 0;

            while (left <= right) {
                long mid = (left + right) >> 1;
                if (mid * b <= a * denom) {
                    numerator = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            left = 0;
            right = 100000;
            long num2 = 0, den2 = denom;

            while (left <= right) {
                long mid = (left + right) >> 1;
                if (mid * b < a * denom) {
                    left = mid + 1;
                } else {
                    num2 = mid;
                    right = mid - 1;
                }
            }

            double diff2 = Math.abs((double) num2 / den2 - (double) a / b);
            double diff1 = Math.abs((double) numerator / denom - (double) a / b);

            if (diff2 + 1e-8 < diff1) {
                numerator = num2;
                denom = den2;
                diff1 = diff2;
            }

            long g = computeGCD(numerator, denom);
            if (diff1 < minDifference) {
                bestNum = numerator / g;
                bestDen = denom / g;
                minDifference = diff1;
            }
        }

        System.out.println(bestNum + "/" + bestDen);
        sc.close();
    }
}
